frappe.listview_settings['Attendance Request'] = {
    get_indicator: function (doc) {
        const map = {
            'Late \u226415 min': 'yellow',
            'Late 15-30 min': 'orange',
            'Late 30-60 min': 'purple',
            'Late 1-2 hr': 'pink',
            'Late >2 hr': 'red'
        };
        if (doc.custom_late_category && map[doc.custom_late_category]) {
            return [__(doc.custom_late_category), map[doc.custom_late_category], 'custom_late_category,=,' + doc.custom_late_category];
        }
        if (doc.docstatus === 1) return [__('Approved'), 'green', 'docstatus,=,1'];
        return [__('Pending'), 'grey', 'docstatus,=,0'];
    }
};

frappe.ui.form.on('Logikview Appraisal', {
    refresh(frm) {
        const me = frappe.session.user;
        const st = frm.doc.workflow_state;
        const isEmp = me === frm.doc.employee_user;
        const isRO  = me === frm.doc.ro_user;
        const isD1  = me === frm.doc.first_director_user;
        const isD2  = me === frm.doc.second_director_user;
        const isHR  = frappe.user.has_role('HR Manager') || frappe.user.has_role('System Manager');

        const empEdit = (st === 'Pending Self-Assessment') && (isEmp || isHR);
        const roEdit  = (st === 'Pending Manager Review')   && (isRO  || isHR);
        const d1Edit  = (st === 'Pending Director Review')  && (isD1  || isHR);
        const d2Edit  = (st === 'Pending Final Director')   && (isD2  || isHR);

        // child-table rating columns
        const grid = frm.fields_dict.ratings.grid;
        grid.update_docfield_property('employee_rating', 'read_only', empEdit ? 0 : 1);
        grid.update_docfield_property('ro_rating',       'read_only', roEdit  ? 0 : 1);
        frm.refresh_field('ratings');

        // narratives (employee)
        ['q_accomplishments', 'q_not_accomplished', 'q_goals'].forEach(f =>
            frm.set_df_property(f, 'read_only', empEdit ? 0 : 1));

        // director feedback
        frm.set_df_property('first_director_feedback',  'read_only', d1Edit ? 0 : 1);
        frm.set_df_property('second_director_feedback', 'read_only', d2Edit ? 0 : 1);

        // gentle hint on whose turn it is
        const hint = {
            'Pending Self-Assessment': 'Employee to fill the self-assessment (Your Rating + the three questions).',
            'Pending Manager Review':  'Reporting officer to fill the RO Rating column.',
            'Pending Director Review': 'Director to add their feedback comment.',
            'Pending Final Director':  'Final director (Sumeet) to add closing feedback.',
            'Completed':               'Appraisal completed.'
        }[st];
        if (hint) frm.dashboard.set_headline(hint);
    }
});
